package com.ruoyi.metal.service;
import com.alibaba.fastjson2.JSON;
import com.alibaba.fastjson2.JSONWriter;
import com.ruoyi.common.exception.ServiceException;
import com.ruoyi.common.utils.SecurityUtils;
import com.ruoyi.metal.security.FactoryScope;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import static com.ruoyi.metal.service.StorageSupport.*;

@Service
public class ProductionBatchReverseService {
 private final JdbcTemplate jdbc;private final FactoryScope scope;
 public ProductionBatchReverseService(JdbcTemplate jdbc,FactoryScope scope){this.jdbc=jdbc;this.scope=scope;}
 static Map<String,Object> before(JdbcTemplate jdbc,long f,List<Long> ids){var batches=new ArrayList<Map<String,Object>>();var executions=new ArrayList<Map<String,Object>>();for(long id:ids.stream().sorted().toList()){batches.add(one(jdbc,"SELECT CAST(id AS CHAR) id,lifecycle FROM metal_production_batch WHERE factory_id=? AND id=? FOR UPDATE",f,id));executions.addAll(jdbc.queryForList("SELECT CAST(id AS CHAR) id,status,close_reason,DATE_FORMAT(closed_at,'%Y-%m-%d %H:%i:%s') closed_at,CAST(loss_weight AS CHAR) loss_weight FROM metal_production_execution WHERE factory_id=? AND batch_id=? ORDER BY id FOR UPDATE",f,id));}return new LinkedHashMap<>(Map.of("batches",batches,"executions",executions));}
 static Map<String,Object> snapshot(JdbcTemplate jdbc,long f,long op,Map<String,Object> before){var ids=new TreeSet<Long>();for(var b:maps(before.get("batches")))ids.add(id(b.get("id")));ids.addAll(jdbc.queryForList("SELECT id FROM metal_production_batch WHERE factory_id=? AND origin_operation_id=? ORDER BY id",Long.class,f,op));var bs=new ArrayList<Map<String,Object>>();var es=new ArrayList<Map<String,Object>>();for(long bid:ids){bs.add(one(jdbc,"SELECT CAST(id AS CHAR) batchId,number,lifecycle,version FROM metal_production_batch WHERE factory_id=? AND id=?",f,bid));es.addAll(jdbc.queryForList("SELECT CAST(id AS CHAR) executionId,status,version FROM metal_production_execution WHERE factory_id=? AND batch_id=? ORDER BY id",f,bid));}return Map.of("before",before,"materialBefore",before.get("materialBefore"),"batches",bs,"executions",es);}
 private static String lockSql(String sql){return org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive()&&!org.springframework.transaction.support.TransactionSynchronizationManager.isCurrentTransactionReadOnly()&&!sql.endsWith("FOR UPDATE")?sql+" FOR UPDATE":sql;}
 private Map<String,Object> read(String sql,Object...args){return one(jdbc,lockSql(sql),args);}
 private List<Map<String,Object>> rows(String sql,Object...args){return jdbc.queryForList(lockSql(sql),args);}
 private <T> List<T> rows(String sql,Class<T> type,Object...args){return jdbc.queryForList(lockSql(sql),type,args);}
 public Map<String,Object> context(long operation,Long requested){allow(scope,"metal:production-batch:reverse");return contextInternal(scope.resolveFactory(requested),operation);}
 private Map<String,Object> contextInternal(long f,long operation){var op=read("SELECT id,action,CAST(result AS CHAR) result FROM metal_production_execution_operation WHERE factory_id=? AND id=?",f,operation);var result=JSON.parseObject(text(op.get("result")));var snapshot=result.getJSONObject("reversalSnapshot");var reasons=new ArrayList<String>();if(!Set.of("SPLIT","MERGE").contains(text(op.get("action")))||snapshot==null||snapshot.get("materialBefore")==null)reasons.add("该历史操作未保存完整撤销快照，不能推测恢复");if(!rows("SELECT id FROM metal_production_execution_operation WHERE factory_id=? AND reversal_of=?",f,operation).isEmpty())reasons.add("该操作已经撤销");var bs=snapshot==null?List.<Map<String,Object>>of():maps(snapshot.get("batches"));var es=snapshot==null?List.<Map<String,Object>>of():maps(snapshot.get("executions"));for(var b:bs){long bid=id(b.get("batchId"));var current=read("SELECT version,lifecycle,order_id FROM metal_production_batch WHERE factory_id=? AND id=?",f,bid);if(!text(current.get("lifecycle")).equals(text(b.get("lifecycle"))))reasons.add("批次"+bid+"已变化，须先逆序处理下游");if(!rows("SELECT id FROM metal_production_batch_edge WHERE factory_id=? AND source_batch_id=? AND operation_id<>? AND NOT EXISTS(SELECT 1 FROM metal_production_execution_operation r WHERE r.factory_id=metal_production_batch_edge.factory_id AND r.reversal_of=metal_production_batch_edge.operation_id)",f,bid,operation).isEmpty())reasons.add("批次已有后续拆合或退料承接");if(!rows("SELECT id FROM metal_storage_document WHERE factory_id=? AND batch_id=? AND deleted=0 AND status IN ('DRAFT','PENDING_REVIEW','RETURNED')",f,bid).isEmpty())reasons.add("批次存在待处理仓储单据");if(!rows("SELECT r.id FROM metal_storage_reservation r JOIN metal_storage_reservation_session s ON s.session_id=r.session_id JOIN metal_storage_batch_slice sl ON sl.stock_id=r.stock_id AND sl.factory_id=r.factory_id WHERE r.factory_id=? AND sl.batch_id=? AND (r.stock_slice_id=sl.id OR r.stock_slice_id IS NULL) AND (s.status='BOUND' OR s.status='TEMP' AND s.expires_at>NOW())",f,bid).isEmpty())reasons.add("批次实物存在有效占用");if(!rows("SELECT id FROM metal_production_order WHERE factory_id=? AND id=? AND (deleted<>0 OR status NOT IN ('CREATED','IN_PROGRESS'))",f,current.get("order_id")).isEmpty())reasons.add("工单已结束或删除");}
 for(var e:es){var now=read("SELECT status,version FROM metal_production_execution WHERE factory_id=? AND id=?",f,id(e.get("executionId")));if(!text(now.get("status")).equals(text(e.get("status"))))reasons.add("加工记录已有后续变化");}
 for(var b:bs){b.put("version",read("SELECT version FROM metal_production_batch WHERE factory_id=? AND id=?",f,id(b.get("batchId"))).get("version"));}for(var e:es){e.put("version",read("SELECT version FROM metal_production_execution WHERE factory_id=? AND id=?",f,id(e.get("executionId"))).get("version"));}var expectedIds=new HashSet<Long>();for(var e:es)expectedIds.add(id(e.get("executionId")));for(var b:bs)for(long eid:rows("SELECT id FROM metal_production_execution WHERE factory_id=? AND batch_id=? AND status<>'CANCELLED'",Long.class,f,id(b.get("batchId"))))if(!expectedIds.contains(eid))reasons.add("结果批次已有新加工记录");
 if(snapshot!=null&&snapshot.get("materialBefore")!=null){try{new ProductionBatchMaterialService(jdbc).requireReversibleTransform(f,operation);}catch(ServiceException ex){reasons.add(ex.getMessage());}var beforeIds=new HashSet<Long>();for(var e:maps(snapshot.getJSONObject("before").get("executions")))beforeIds.add(id(e.get("id")));for(var e:es)if(!beforeIds.contains(id(e.get("executionId")))&&!rows("SELECT id FROM metal_production_execution_event WHERE factory_id=? AND execution_id=? AND reversed=0",f,id(e.get("executionId"))).isEmpty())reasons.add("承接加工记录已有有效投入产出或退料，须先逆序处理");}return Map.of("operationId",String.valueOf(operation),"action",op.get("action"),"expectedBatches",bs,"expectedExecutions",es,"allowed",reasons.isEmpty(),"blockingReasons",reasons.stream().distinct().toList());}
 @Transactional(rollbackFor=Exception.class)
 public Map<String,Object> reverse(long operation,Map<String,Object> body){allow(scope,"metal:production-batch:reverse");if(body==null||!Set.of("factoryId","requestId","reason","expectedBatches","expectedExecutions").containsAll(body.keySet()))throw fail("请求包含不支持的字段");long f=scope.resolveFactory(optionalId(body.get("factoryId")));String request=uuid(body.get("requestId")),why=reason(body.get("reason"));var normalized=new TreeMap<String,Object>(body);normalized.remove("requestId");normalized.put("operationId",operation);String fingerprint=hash(normalized);scope.lockFactories(List.of(f));var replay=rows("SELECT action,request_hash,CAST(result AS CHAR) result FROM metal_production_execution_operation WHERE factory_id=? AND actor_id=? AND request_id=? FOR UPDATE",f,SecurityUtils.getUserId(),request);if(!replay.isEmpty()){var row=replay.get(0);if(!"REVERSE_TRANSFORM".equals(row.get("action"))||!fingerprint.equals(row.get("request_hash")))throw conflict("相同请求号内容已变化");return JSON.parseObject(text(row.get("result")));}var ctx=contextInternal(f,operation);if(!Boolean.TRUE.equals(ctx.get("allowed")))throw conflict(String.join("；",(List<String>)ctx.get("blockingReasons")));versions(maps(ctx.get("expectedBatches")),maps(body.getOrDefault("expectedBatches",List.of())),"batchId");versions(maps(ctx.get("expectedExecutions")),maps(body.getOrDefault("expectedExecutions",List.of())),"executionId");var original=read("SELECT CAST(result AS CHAR) result FROM metal_production_execution_operation WHERE factory_id=? AND id=? FOR UPDATE",f,operation);var snapshot=JSON.parseObject(text(original.get("result"))).getJSONObject("reversalSnapshot");long reversal=insert(jdbc,"INSERT INTO metal_production_execution_operation(factory_id,actor_id,request_id,action,request_hash,result,reason,reversal_of) VALUES(?,?,?,'REVERSE_TRANSFORM',?,'{}',?,?)",f,SecurityUtils.getUserId(),request,fingerprint,why,operation);new ProductionBatchMaterialService(jdbc).reverseTransform(f,operation,reversal);
 var oldBatches=maps(snapshot.getJSONObject("before").get("batches"));var oldExec=maps(snapshot.getJSONObject("before").get("executions"));var originalBatchIds=new HashSet<Long>();for(var b:oldBatches){originalBatchIds.add(id(b.get("id")));jdbc.update("UPDATE metal_production_batch SET lifecycle=?,version=version+1,update_time=NOW() WHERE factory_id=? AND id=?",b.get("lifecycle"),f,id(b.get("id")));}for(var b:maps(ctx.get("expectedBatches")))if(!originalBatchIds.contains(id(b.get("batchId"))))jdbc.update("UPDATE metal_production_batch SET lifecycle='CANCELLED',version=version+1,update_time=NOW() WHERE factory_id=? AND id=?",f,id(b.get("batchId")));var oldExecIds=new HashSet<Long>();for(var e:oldExec){oldExecIds.add(id(e.get("id")));jdbc.update("UPDATE metal_production_execution SET status=?,close_reason=?,closed_at=?,loss_weight=?,version=version+1 WHERE factory_id=? AND id=?",e.get("status"),e.get("close_reason"),e.get("closed_at"),e.get("loss_weight"),f,id(e.get("id")));}for(var e:maps(ctx.get("expectedExecutions")))if(!oldExecIds.contains(id(e.get("executionId"))))jdbc.update("UPDATE metal_production_execution SET status='CANCELLED',version=version+1,close_reason=?,closed_at=NOW() WHERE factory_id=? AND id=?",why,f,id(e.get("executionId")));var result=new LinkedHashMap<String,Object>();result.put("operationId",String.valueOf(reversal));result.put("reversalOf",String.valueOf(operation));result.put("requestId",request);result.put("committed",true);result.put("batchId",oldBatches.get(0).get("id").toString());result.put("affectedBatchIds",maps(ctx.get("expectedBatches")).stream().map(b->b.get("batchId")).toList());jdbc.update("UPDATE metal_production_execution_operation SET result=? WHERE factory_id=? AND id=?",JSON.toJSONString(result,JSONWriter.Feature.WriteMapNullValue),f,reversal);return result;}
 static void versions(List<Map<String,Object>> expected,List<Map<String,Object>> actual,String key){var map=new HashMap<Long,Integer>();for(var row:actual)if(map.put(id(row.get(key)),version(row.get("version")))!=null)throw conflict("版本对象重复");if(map.size()!=expected.size())throw conflict("必须提供完整影响范围版本");for(var row:expected)if(!Objects.equals(map.get(id(row.get(key))),version(row.get("version"))))throw conflict("对象版本已变化");}
 private static ServiceException conflict(String message){return new ServiceException(message,409);}
}

